// defaultStepSeconds is the fallback bucket size, in seconds, used when the
// query parameters do not specify a valid step.
const defaultStepSeconds uint64 = 60

// defaultLookback is used to derive the query start time when the parameters
// do not specify a lookback duration.
const defaultLookback = time.Hour

// errNotImplemented is returned by the metrics queries that are not yet
// supported by the ClickHouse backend.
var errNotImplemented = errors.New("not implemented")

var _ metricstore.Reader = (*Reader)(nil)

// Reader retrieves aggregated trace metrics (SPM) from ClickHouse.
type Reader struct {
	conn driver.Conn
}

// NewReader returns a new ClickHouse metrics store Reader backed by the given
// ClickHouse driver connection.
func NewReader(conn driver.Conn) *Reader {
	return &Reader{conn: conn}
}

// GetLatencies retrieves latency metrics grouped by service and, optionally, by
// operation.
func (r *Reader) GetLatencies(ctx context.Context, params *metricstore.LatenciesQueryParameters) (*metrics.MetricFamily, error) {
	name := "service_latencies"
	query := sql.SelectLatencies
	if params.GroupByOperation {
		name = "service_operation_latencies"
		query = sql.SelectLatenciesByOperation
	}

	end := time.Now()
	if params.EndTime != nil {
		end = *params.EndTime
	}
	lookback := defaultLookback
	if params.Lookback != nil {
		lookback = *params.Lookback
	}
	start := end.Add(-lookback)

	rows, err := r.conn.Query(
		ctx,
		query,
		stepSeconds(params.BaseQueryParameters),
		params.Quantile,
		params.ServiceNames,
		convertSpanKinds(params.SpanKinds),
		start,
		end,
	)
	if err != nil {
		return nil, fmt.Errorf("failed to query latencies: %w", err)
	}
	defer rows.Close()

	family, err := r.scanMetrics(rows, name, params.GroupByOperation)
	if err != nil {
		return nil, err
	}
	return family, nil
}

// scanMetrics reads all rows into a MetricFamily. Rows sharing the same set of
// labels (service, or service and operation) are merged into a single Metric
// with one MetricPoint per row.
func (*Reader) scanMetrics(rows driver.Rows, name string, groupByOperation bool) (*metrics.MetricFamily, error) {
	family := &metrics.MetricFamily{
		Name:    name,
		Type:    metrics.MetricType_GAUGE,
		Metrics: []*metrics.Metric{},
	}

	// index maps a label key to the position of its Metric in family.Metrics so
	// that data points for the same series are appended in query order.
	index := make(map[string]int)

	for rows.Next() {
		var row metricsRow
		if err := rows.ScanStruct(&row); err != nil {
			return nil, fmt.Errorf("failed to scan metrics row: %w", err)
		}

		key := row.ServiceName
		if groupByOperation {
			key = row.ServiceName + "\x00" + row.Operation
		}

		i, ok := index[key]
		if !ok {
			labels := []*metrics.Label{
				{Name: "service_name", Value: row.ServiceName},
			}
			if groupByOperation {
				labels = append(labels, &metrics.Label{Name: "operation", Value: row.Operation})
			}
			family.Metrics = append(family.Metrics, &metrics.Metric{
				Labels:       labels,
				MetricPoints: []*metrics.MetricPoint{},
			})
			i = len(family.Metrics) - 1
			index[key] = i
		}

		family.Metrics[i].MetricPoints = append(family.Metrics[i].MetricPoints, toMetricPoint(row))
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating metrics rows: %w", err)
	}

	return family, nil
}

// toMetricPoint converts a single metrics row into a gauge MetricPoint holding
// a double value.
func toMetricPoint(row metricsRow) *metrics.MetricPoint {
	return &metrics.MetricPoint{
		Timestamp: &types.Timestamp{
			Seconds: row.Timestamp.Unix(),
			Nanos:   int32(row.Timestamp.Nanosecond()),
		},
		Value: &metrics.MetricPoint_GaugeValue{
			GaugeValue: &metrics.GaugeValue{
				Value: &metrics.GaugeValue_DoubleValue{DoubleValue: row.Value},
			},
		},
	}
}

