// stepSeconds converts the query step duration to whole seconds. It falls back
// to defaultStepSeconds when the step is nil, zero, or negative, clamps positive
// sub-second values to 1, and truncates any fractional seconds otherwise.
func stepSeconds(p metricstore.BaseQueryParameters) uint64 {
	if p.Step == nil || *p.Step <= 0 {
		return defaultStepSeconds
	}
	seconds := *p.Step / time.Second
	if seconds < 1 {
		return 1
	}
	return uint64(seconds)
}

// convertSpanKinds maps OpenTelemetry span kind names to the lowercase
// representation stored in ClickHouse. Unknown kinds are omitted from the
// result.
func convertSpanKinds(kinds []string) []string {
	converted := make([]string, 0, len(kinds))
	for _, kind := range kinds {
		switch kind {
		case "SPAN_KIND_SERVER":
			converted = append(converted, "server")
		case "SPAN_KIND_CLIENT":
			converted = append(converted, "client")
		case "SPAN_KIND_UNSPECIFIED":
			converted = append(converted, "")
		default:
			// Unrecognized span kinds are skipped.
		}
	}
	return converted
}
