func TestSanity(t *testing.T) {
	// stepSeconds
	sub := 500 * time.Millisecond
	if got := stepSeconds(metricstore.BaseQueryParameters{Step: &sub}); got != 1 {
		t.Fatalf("sub-second step = %d, want 1", got)
	}
	frac := 2500 * time.Millisecond
	if got := stepSeconds(metricstore.BaseQueryParameters{Step: &frac}); got != 2 {
		t.Fatalf("fractional step = %d, want 2", got)
	}
	if got := stepSeconds(metricstore.BaseQueryParameters{}); got != defaultStepSeconds {
		t.Fatalf("nil step = %d, want %d", got, defaultStepSeconds)
	}
	neg := -5 * time.Second
	if got := stepSeconds(metricstore.BaseQueryParameters{Step: &neg}); got != defaultStepSeconds {
		t.Fatalf("neg step = %d, want %d", got, defaultStepSeconds)
	}

	// convertSpanKinds
	got := convertSpanKinds([]string{"SPAN_KIND_SERVER", "SPAN_KIND_CLIENT", "SPAN_KIND_UNSPECIFIED", "BOGUS"})
	want := []string{"server", "client", ""}
	if len(got) != len(want) {
		t.Fatalf("convertSpanKinds len = %v, want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("convertSpanKinds[%d] = %q, want %q", i, got[i], want[i])
		}
	}

	// GetLatencies grouped by operation
	rows := &clickhousetest.Rows[metricsRow]{
		Data: []metricsRow{
			{Timestamp: time.Unix(100, 0), ServiceName: "svc", Operation: "op1", Value: 1.5},
			{Timestamp: time.Unix(160, 0), ServiceName: "svc", Operation: "op1", Value: 2.5},
			{Timestamp: time.Unix(100, 0), ServiceName: "svc", Operation: "op2", Value: 3.5},
		},
		ScanFn: func(dest any, src metricsRow) error {
			*dest.(*metricsRow) = src
			return nil
		},
	}
	drv := &clickhousetest.Driver{
		QueryResponses: map[string]*clickhousetest.QueryResponse{
			sql.SelectLatenciesByOperation: {Rows: rows},
		},
	}
	r := NewReader(drv)
	fam, err := r.GetLatencies(context.Background(), &metricstore.LatenciesQueryParameters{
		BaseQueryParameters: metricstore.BaseQueryParameters{GroupByOperation: true},
		Quantile:            0.95,
	})
	if err != nil {
		t.Fatal(err)
	}
	if fam.Name != "service_operation_latencies" {
		t.Fatalf("name = %q", fam.Name)
	}
	if len(fam.Metrics) != 2 {
		t.Fatalf("metrics count = %d, want 2", len(fam.Metrics))
	}
	m0 := fam.Metrics[0]
	if len(m0.Labels) != 2 || m0.Labels[0].Name != "service_name" || m0.Labels[1].Name != "operation" {
		t.Fatalf("labels = %+v", m0.Labels)
	}
	if len(m0.MetricPoints) != 2 {
		t.Fatalf("op1 points = %d, want 2", len(m0.MetricPoints))
	}
	if m0.MetricPoints[0].GetGaugeValue().GetDoubleValue() != 1.5 {
		t.Fatalf("point value = %v", m0.MetricPoints[0].GetGaugeValue().GetDoubleValue())
	}

	// error path
	drvErr := &clickhousetest.Driver{
		QueryResponses: map[string]*clickhousetest.QueryResponse{
			sql.SelectLatencies: {Rows: &clickhousetest.Rows[metricsRow]{RowsErr: context.Canceled}},
		},
	}
	_, err = NewReader(drvErr).GetLatencies(context.Background(), &metricstore.LatenciesQueryParameters{})
	if err == nil || !contains(err.Error(), "error iterating metrics rows") {
		t.Fatalf("iter err = %v", err)
	}
}

func contains(s, sub string) bool {
	return len(s) >= len(sub) && (s == sub || indexOf(s, sub) >= 0)
}

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}
